        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "weatherIcon",
      "src": "resources/base/media/icon_weather1.png",
      "use": "weather alert glyph",
      "description": "天气状态图标，用于登机牌上的天气提醒。",
      "bindTo": "/asset/weatherIcon",
      "static": true
    }
  ]
}

